    // Numeric comparisons
    let _ = EquityField::PeRatio.gt(5.0); // P/E > 5
    let _ = EquityField::PeRatio.lt(30.0); // P/E < 30
    let _ = EquityField::PeRatio.gte(10.0); // P/E >= 10
